#pragma once
/*
 * spi_lnk.h stub — PC port of the SPI link layer interface.
 *
 * On the embedded target this header is generated by the SPI driver build
 * and exposes the transmit buffer and addCommand() API used by AudioSpiGateway.
 *
 * Here we provide the minimal type definitions and extern declarations needed
 * so AudioSpiGateway.c compiles. The actual symbols are defined in
 * pc_port/src/spi_stubs.c with logging-only behaviour.
 */
#include <stdint.h>

/*
 * Transmit buffer — on the target this is a circular ring buffer driven by
 * the SPI DMA interrupt handler. `head` is the write position; `tail` is
 * owned by the ISR. We replicate only the fields AudioSpiGateway.c touches.
 */
typedef struct {
    uint8_t  data[256];   /* raw byte ring */
    uint16_t head;        /* write position (AudioSpiGateway writes here) */
    uint16_t tail;        /* read position  (ISR; unused in stub)         */
} ModemTxBufType;

/* Exposed by spi_lnk.c on target; by spi_stubs.c on PC */
extern void          addCommand(uint8_t command);
extern int           addingCommands;
extern uint16_t      globalModemTxBuf_head_shadow;
extern ModemTxBufType globalModemTxBuf;
